import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor list search and status filter", () => {
  test(
    "search and the status filter apply together",
    { tag: "@LIF-14" },
    async ({ apiAs, factory }) => {
      // Arrange
      const word = uniqueName("Lif14Search").replace(/\s+/g, "");
      const draft = await factory.vendor({ name: `${word} draft` });
      const review = await factory.vendorInReview({ name: `${word} review` });
      const member = await apiAs("member");

      // Act
      const response = await member.get("/api/vendors", {
        params: { q: word, status: "in_review" },
      });

      // Assert
      const page = await expectStatus<{ items: { id: string; name: string; status: string }[]; total: number }>(
        response,
        200,
      );
      expect(page.items.map((v) => v.id)).toEqual([review.vendor.id]);
      expect(page.items[0].status).toBe("in_review");
      expect(page.items.some((v) => v.id === draft.id)).toBe(false);
      expect(page.total).toBe(1);
    },
  );
});
